function ground(x){return 426+37*Math.sin(x*.0031)+17*Math.sin(x*.0083+1.4)+7*Math.sin(x*.021+.6)+4*Math.sin(x*.0014+2.2)}
let car,camX=0,camY=0,last=0,acc=0,bolts=0,best=Number(localStorage.getItem('dustyBest')||0),collected=new Set(),toastTimer=0;
function reset(){car={x:0,y:ground(0)-43,vx:0,vy:0,a:0,w:0};camX=-W*.30/scale;camY=0;bolts=0;collected.clear();acc=0;last=performance.now()}
$('reset').addEventListener('click',reset);
function rotate(x,y,a){const c=Math.cos(a),s=Math.sin(a);return{x:x*c-y*s,y:x*s+y*c}}
function wheelAnchor(sign){const p=rotate(sign*39,13,car.a);return{x:car.x+p.x,y:car.y+p.y,rx:p.x,ry:p.y}}
function physics(dt){const throttle=(keys.gas?1:0)-(keys.brake?1:0),steer=(keys.right?1:0)-(keys.left?1:0);let fx=0,fy=360,torque=0,contacts=0;
 for(const sign of [-1,1]){const p=wheelAnchor(sign),g=ground(p.x),wheelGround=g-14,compression=p.y+16-wheelGround,pointVy=car.vy+car.w*p.rx;
  if(compression>0){contacts++;let spring=Math.max(0,Math.min(1150,compression*158-pointVy*24));fy-=spring;torque+=p.rx*(-spring);if(throttle){const drive=throttle*590;fx+=drive;torque+=(-p.ry)*drive}if(keys.brake&&Math.abs(car.vx)>4)fx-=Math.sign(car.vx)*300;
 }
 }
 if(contacts===0){torque+=steer*780}else{torque+=steer*510}
 fx-=car.vx*(contacts?1.05:.28);torque-=car.w*850;
 car.vx+=fx*dt;car.vy+=fy*dt;car.w+=torque/2050*dt;
 car.vx=Math.max(-135,Math.min(300,car.vx));car.w=Math.max(-3.3,Math.min(3.3,car.w));
 car.x+=car.vx*dt;car.y+=car.vy*dt;car.a+=car.w*dt;
 // A forgiving underside collision keeps the ride moving after hard landings.
 const belly=rotate(0,21,car.a),bottom=car.y+belly.y,g=ground(car.x);
 if(bottom>g-5){car.y-=bottom-(g-5);if(car.vy>0)car.vy*=-.12;car.vx*=.985;car.w*=.96}
 if(car.y>900){car.y=ground(car.x)-48;car.vy=0;car.a=0;car.w=0}
 const index=Math.max(0,Math.floor((car.x-170)/280));for(let i=index-1;i<=index+1;i++){if(i<0||collected.has(i))continue;const x=210+i*280,y=ground(x)-91-Math.sin(i*8)*7;if(Math.hypot(car.x-x,car.y-27-y)<39){collected.add(i);bolts++;showToast()}}
}
function showToast(){const el=$('toast');el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),700)}
function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
function drawSky(t){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#12263a');g.addColorStop(.52,'#527986');g.addColorStop(1,'#e6a76f');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 const sunX=W*.77-(camX*.018%W),sunY=H*.25;const halo=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,H*.24);halo.addColorStop(0,'#ffe7b6c8');halo.addColorStop(.22,'#f3c28c42');halo.addColorStop(1,'#f3c28c00');ctx.fillStyle=halo;ctx.fillRect(sunX-H*.24,sunY-H*.24,H*.48,H*.48);ctx.fillStyle='#ffe2ad';ctx.beginPath();ctx.arc(sunX,sunY,Math.min(30,H*.055),0,Math.PI*2);ctx.fill();
 // distant ridge silhouettes
 for(let layer=0;layer<3;layer++){const par=.025+layer*.038,base=H*(.49+layer*.075),amp=H*(.065-layer*.008),shift=(camX*scale*par)%240;ctx.beginPath();ctx.moveTo(-250, H);for(let x=-260;x<=W+260;x+=12){let wx=x+shift;let y=base-Math.abs(Math.sin(wx*.0031+layer*2))*amp-Math.abs(Math.sin(wx*.008+layer))*amp*.42;ctx.lineTo(x,y)}ctx.lineTo(W+300,H);ctx.closePath();ctx.fillStyle=['#354f5c','#2b4952','#25434a'][layer];ctx.fill()}
 // small atmospheric clouds, moving slowly
 for(let i=0;i<5;i++){const x=((i*247-camX*scale*.04+t*.006)%(W+180)+W+180)%(W+180)-70,y=H*(.18+(i%3)*.07);ctx.fillStyle='#f8e6d11c';ctx.beginPath();ctx.ellipse(x,y,36,7,0,0,Math.PI*2);ctx.ellipse(x+20,y-5,25,9,0,0,Math.PI*2);ctx.fill()}
}

