 for(let i=0;i<5;i++){const x=((i*247-camX*scale*.04+t*.006)%(W+180)+W+180)%(W+180)-70,y=H*(.18+(i%3)*.07);ctx.fillStyle='#f8e6d11c';ctx.beginPath();ctx.ellipse(x,y,36,7,0,0,Math.PI*2);ctx.ellipse(x+20,y-5,25,9,0,0,Math.PI*2);ctx.fill()}
}
function drawGround(){const left=camX-120,right=camX+W/scale+140;ctx.beginPath();ctx.moveTo(left,ground(left));for(let x=left;x<=right;x+=7)ctx.lineTo(x,ground(x));ctx.lineTo(right,1000);ctx.lineTo(left,1000);ctx.closePath();const soil=ctx.createLinearGradient(0,390,0,720);soil.addColorStop(0,'#9b6946');soil.addColorStop(.14,'#754c38');soil.addColorStop(1,'#362f31');ctx.fillStyle=soil;ctx.fill();ctx.beginPath();for(let x=left;x<=right;x+=5){const y=ground(x);if(x===left)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#e7b577';ctx.lineWidth=4;ctx.stroke();
 // Terrain strata and sparse scrub make the landscape read at speed.
 ctx.beginPath();for(let x=left;x<=right;x+=9){const y=ground(x)+30+Math.sin(x*.017)*5;if(x===left)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.strokeStyle='#bd815433';ctx.lineWidth=2;ctx.stroke();
 const first=Math.floor(left/110);for(let n=first;n<right/110;n++){const x=n*110+((n*47)%31),y=ground(x);if(n%3===0){ctx.strokeStyle='#273e3d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y-14-(n%4)*2);ctx.moveTo(x-3,y-7);ctx.lineTo(x-9,y-12);ctx.moveTo(x-3,y-10);ctx.lineTo(x+3,y-16);ctx.stroke();ctx.fillStyle='#607363';ctx.beginPath();ctx.ellipse(x+12,y-2,5,2,0,0,7);ctx.fill()}else{ctx.fillStyle=n%2?'#576359':'#796955';ctx.beginPath();ctx.ellipse(x,y-2,4+(n%4),2,0,0,7);ctx.fill()}}
 // Route markers every 500 m.
 const marker=Math.floor(left/500);for(let n=marker;n<=right/500;n++){if(n<1)continue;const x=n*500,y=ground(x);ctx.fillStyle='#f2d6a5';ctx.fillRect(x-2,y-42,4,42);ctx.fillStyle='#c8f36a';ctx.beginPath();ctx.moveTo(x,y-42);ctx.lineTo(x+24,y-36);ctx.lineTo(x,y-29);ctx.closePath();ctx.fill();ctx.fillStyle='#29424a';ctx.font='bold 8px system-ui';ctx.textAlign='center';ctx.fillText(String(n/2),x+8,y-33)}
}
function drawBolt(x,y,t){ctx.save();ctx.translate(x,y+Math.sin(t*.004+x)*3);ctx.rotate(Math.sin(x)*.15);ctx.shadowColor='#ffd366';ctx.shadowBlur=14;ctx.fillStyle='#ffd66b';ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#fff0ad';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,6,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#945e2e';ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',0,0);ctx.restore()}
function drawCar(){const wheels=[wheelAnchor(-1),wheelAnchor(1)];for(const p of wheels){const wy=ground(p.x)-14;ctx.strokeStyle='#25323a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x,wy);ctx.stroke();ctx.save();ctx.translate(p.x,wy);ctx.rotate(-car.x*.05+car.w*.1);ctx.fillStyle='#17222a';ctx.beginPath();ctx.arc(0,0,14,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#718080';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#aeb5a6';ctx.lineWidth=2;for(let i=0;i<4;i++){ctx.rotate(Math.PI/2);ctx.beginPath();ctx.moveTo(0,-2);ctx.lineTo(0,-8);ctx.stroke()}ctx.fillStyle='#e5c992';ctx.beginPath();ctx.arc(0,0,3,0,7);ctx.fill();ctx.restore()}
 ctx.save();ctx.translate(car.x,car.y);ctx.rotate(car.a);
 // soft chassis shadow + suspension frame
 ctx.fillStyle='#101e2755';ctx.beginPath();ctx.ellipse(0,27,51,7,0,0,7);ctx.fill();
 ctx.fillStyle='#2c4347';ctx.beginPath();ctx.moveTo(-44,7);ctx.lineTo(45,7);ctx.lineTo(42,14);ctx.lineTo(-42,14);ctx.closePath();ctx.fill();
 // rugged body
 ctx.beginPath();ctx.moveTo(-52,7);ctx.lineTo(-48,-10);ctx.quadraticCurveTo(-45,-16,-31,-17);ctx.lineTo(-17,-18);ctx.lineTo(-6,-31);ctx.quadraticCurveTo(-2,-35,7,-35);ctx.lineTo(27,-34);ctx.quadraticCurveTo(35,-32,41,-20);ctx.lineTo(49,-17);ctx.quadraticCurveTo(54,-14,54,-7);ctx.lineTo(52,8);ctx.quadraticCurveTo(48,13,39,13);ctx.lineTo(-43,13);ctx.quadraticCurveTo(-50,12,-52,7);ctx.closePath();ctx.fillStyle='#d87543';ctx.fill();ctx.strokeStyle='#f6b36c';ctx.lineWidth=2;ctx.stroke();
 // cabin glass
 ctx.beginPath();ctx.moveTo(-11,-20);ctx.lineTo(-3,-31);ctx.quadraticCurveTo(0,-33,7,-33);ctx.lineTo(11,-20);ctx.closePath();ctx.fillStyle='#203c4a';ctx.fill();ctx.strokeStyle='#f3c07d';ctx.lineWidth=1.5;ctx.stroke();ctx.beginPath();ctx.moveTo(14,-20);ctx.lineTo(10,-33);ctx.lineTo(26,-32);ctx.quadraticCurveTo(31,-29,36,-20);ctx.closePath();ctx.fillStyle='#254451';ctx.fill();ctx.stroke();
 // roof rack and hood strip
 ctx.strokeStyle='#f6d29a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8,-37);ctx.lineTo(27,-37);ctx.moveTo(-5,-37);ctx.lineTo(-8,-33);ctx.moveTo(24,-37);ctx.lineTo(27,-33);ctx.stroke();ctx.fillStyle='#f4cf7a';ctx.fillRect(40,-13,7,4);ctx.fillStyle='#f2e5c2';ctx.fillRect(50,-10,3,5);ctx.fillStyle='#a84f3a';ctx.fillRect(-48,-9,4,5);ctx.fillStyle='#384b50';ctx.fillRect(-30,0,39,4);
 // hood badge + door seam
 ctx.strokeStyle='#8c4938';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(11,-16);ctx.lineTo(12,9);ctx.moveTo(35,-15);ctx.lineTo(34,8);ctx.stroke();ctx.fillStyle='#c8f36a';ctx.beginPath();ctx.arc(22,-11,2,0,7);ctx.fill();ctx.restore();
}

